def is_min_heap(values):
    for child in range(1, len(values)):
        parent = (child - 1) // 2
        if values[parent] > values[child]:
            return False
    return True

print(is_min_heap([1, 3, 2, 7]))
print(is_min_heap([1, 4, 2, 3]))
print(is_min_heap([]))
print(is_min_heap([5]))

import heapq

def handle_heap_commands(commands):
    heap = []
    observations = []
    for action, value in commands:
        if action == "push":
            heapq.heappush(heap, value)
        elif action == "pop":
            observations.append(heapq.heappop(heap) if heap else None)
        elif action == "peek":
            observations.append(heap[0] if heap else None)
        else:
            raise ValueError("unknown command")
    remaining = []
    while heap:
        remaining.append(heapq.heappop(heap))
    return observations, remaining

print(handle_heap_commands([("pop", None), ("push", 3), ("push", 1), ("peek", None), ("pop", None)]))
print(handle_heap_commands([]))
print(handle_heap_commands([("push", 2), ("push", 2), ("pop", None)]))
try:
    handle_heap_commands([("sort", None)])
except ValueError:
    print("ValueError")
